<section aria-labelledby="form-fields-title"><h3 id="form-fields-title">Fields</h3><div id="form-field-list"><?php foreach($fields as $index=>$field):$prefix='fields['.$index.']';$rowErrors=$fieldErrors[(string)$index]??[];?><fieldset class="admin-panel form-field-row"><legend>Field <?=((int)$index)+1?></legend><?php foreach($rowErrors as $error):?><p class="admin-field__help" role="alert"><?=htmlspecialchars((string)$error,ENT_QUOTES,'UTF-8')?></p><?php endforeach;?><div class="admin-field"><label class="admin-field__label" for="field-key-<?=$index?>">Field key</label><input id="field-key-<?=$index?>" name="<?=$prefix?>[field_key]" type="text" maxlength="100" required value="<?=htmlspecialchars((string)($field['field_key']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><label class="admin-field__label" for="field-label-<?=$index?>">Label</label><input id="field-label-<?=$index?>" name="<?=$prefix?>[label]" type="text" maxlength="150" required value="<?=htmlspecialchars((string)($field['label']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><label class="admin-field__label" for="field-type-<?=$index?>">Type</label><select id="field-type-<?=$index?>" name="<?=$prefix?>[field_type]"><?php foreach($fieldTypes as $type):?><option value="<?=$type?>" <?=($field['field_type']??'text')===$type?'selected':''?>><?=htmlspecialchars(ucfirst($type),ENT_QUOTES,'UTF-8')?></option><?php endforeach;?></select></div><div class="admin-field"><label class="admin-field__label" for="field-order-<?=$index?>">Sort order</label><input id="field-order-<?=$index?>" name="<?=$prefix?>[sort_order]" type="number" min="0" required value="<?=htmlspecialchars((string)($field['sort_order']??$index),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><input id="field-required-<?=$index?>" name="<?=$prefix?>[is_required]" type="checkbox" value="1" <?=!empty($field['is_required'])?'checked':''?>><label class="admin-field__label" for="field-required-<?=$index?>">Required</label></div><div class="admin-field"><label class="admin-field__label" for="field-min-<?=$index?>">Minimum length</label><input id="field-min-<?=$index?>" name="<?=$prefix?>[min_length]" type="number" min="0" value="<?=htmlspecialchars((string)($field['min_length']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><label class="admin-field__label" for="field-max-<?=$index?>">Maximum length</label><input id="field-max-<?=$index?>" name="<?=$prefix?>[max_length]" type="number" min="0" value="<?=htmlspecialchars((string)($field['max_length']??''),ENT_QUOTES,'UTF-8')?>"></div><fieldset data-options><legend>Select options</legend><?php foreach(($field['options']??[]) as $optionIndex=>$option):$optionPrefix=$prefix.'[options]['.$optionIndex.']';?><div class="admin-field"><label class="admin-field__label" for="option-value-<?=$index?>-<?=$optionIndex?>">Option value</label><input id="option-value-<?=$index?>-<?=$optionIndex?>" name="<?=$optionPrefix?>[option_value]" type="text" maxlength="100" value="<?=htmlspecialchars((string)($option['option_value']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><label class="admin-field__label" for="option-label-<?=$index?>-<?=$optionIndex?>">Option label</label><input id="option-label-<?=$index?>-<?=$optionIndex?>" name="<?=$optionPrefix?>[option_label]" type="text" maxlength="150" value="<?=htmlspecialchars((string)($option['option_label']??''),ENT_QUOTES,'UTF-8')?>"></div><div class="admin-field"><label class="admin-field__label" for="option-order-<?=$index?>-<?=$optionIndex?>">Option sort order</label><input id="option-order-<?=$index?>-<?=$optionIndex?>" name="<?=$optionPrefix?>[sort_order]" type="number" min="0" value="<?=htmlspecialchars((string)($option['sort_order']??$optionIndex),ENT_QUOTES,'UTF-8')?>"></div><?php endforeach;?><button class="admin-button admin-button--secondary" type="button" data-add-option>Add select option</button></fieldset><button class="admin-button admin-button--secondary" type="button"