<script>document.addEventListener('click',function(event){if(event.target.matches('[data-remove-field]')){event.target.closest('.form-field-row').remove();return;}if(event.target.matches('[data-add-option]')){var i=Date.now(),field=event.target.closest('.form-field-row'),key=field.querySelector('[name$="[field_key]"]').name.match(/^fields\[([^\]]+)/)[1],row=document.createElement('div');row.className='admin-field';row.innerHTML='<label class="admin-field__label">Option value <input name="fields['+key+'][options]['+i+'][option_value]" maxlength="100"></label><label class="admin-field__label">Option label <input name="fields['+key+'][options]['+i+'][option_label]" maxlength="150"></label><label class="admin-field__label">Option sort order <input name="fields['+key+'][options]['+i+'][sort_order]" type="number" min="0" value="0"></label>';event.target.before(row);return;}if(event.target.matches('[data-add-field]')){var i=Date.now(),root=document.getElementById('form-field-list'),field=document.createElement('fieldset');field.className='admin-panel form-field-row';field.innerHTML='<legend>New field</legend><div class="admin-field"><label class="admin-field__label">Field key <input name="fields['+i+'][field_key]" maxlength="100" required></label></div><div class="admin-field"><label class="admin-field__label">Label <input name="fields['+i+'][label]" maxlength="150" required></label></div><div class="admin-field"><label class="admin-field__label">Type <select name="fields['+i+'][field_type]"><option value="text">Text</option><option value="email">Email</option><option value="textarea">Textarea</option><option value="select">Select</option><option value="checkbox">Checkbox</option></select></label></div><div class="admin-field"><label class="admin-field__label">Sort order <input name="fields['+i+'][sort_order]" type="number" min="0" required value="0"></label></div><div class="admin-field"><input id="required-'+i+'" name="fields['+i+'][is_required]" type="checkbox" value="1"><label class="admin-field__label" for="required-'+i+'">Required</label></div><div class="admin-field"><label class="admin-field__label">Minimum length <input name="fields['+i+'][min_length]" type="number" min="0"></label></div><div class="admin-field"><label class="admin-field__label">Maximum length <input name="fields['+i+'][max_length]" type="number" min="0"></label></div><fieldset data-options><legend>Select options</legend><button class="admin-button admin-button--secondary" type="button" data-add-option>Add select option</button></fieldset><button class="admin-button admin-button--secondary" type="button" data-remove-field>Remove field</button>';root.appendChild(field);}});</script>
